-- These messages were generated by the retired diet publisher.
delete from public.care_notifications
where source_key like 'diet:%' or (title='Novo plano alimentar' and body='Seu plano foi atualizado pela nutricionista.');

alter table public.patient_daily_habits
  drop constraint patient_daily_habits_habit_check,
  add constraint patient_daily_habits_habit_check check (habit in ('bowel','strength','cardio','diet','alcohol','free_meal')),
  add column cardio_minutes smallint check (cardio_minutes is null or (habit='cardio' and cardio_minutes between 1 and 1440)),
  add column meal_description text,
  add constraint free_meal_description_check check (
    (habit='free_meal' and meal_description is not null and length(btrim(meal_description)) between 1 and 1000)
    or (habit<>'free_meal' and meal_description is null)
  );
grant update(cardio_minutes,meal_description), insert(meal_description) on public.patient_daily_habits to authenticated;

create function public.set_free_meal_note(p_patient uuid, p_day date, p_description text)
returns void language plpgsql security invoker set search_path='' as $$
begin
  if not public.can_record_daily_habit(p_patient,p_day) then
    raise exception 'Não é possível alterar o relato desta data.' using errcode='42501';
  end if;
  if p_description is null then
    delete from public.patient_daily_habits where patient_id=p_patient and habit_date=p_day and habit='free_meal';
  else
    insert into public.patient_daily_habits(patient_id,habit_date,habit,level,meal_description)
      values(p_patient,p_day,'free_meal',1,btrim(p_description))
      on conflict(patient_id,habit_date,habit) do update set meal_description=excluded.meal_description
      where public.patient_daily_habits.meal_description is distinct from excluded.meal_description;
  end if;
end $$;
revoke all on function public.set_free_meal_note(uuid,date,text) from public,anon;
grant execute on function public.set_free_meal_note(uuid,date,text) to authenticated;
notify pgrst,'reload schema';
